define(['core/notification'],function(Notification){"use strict";var config={},elements={},state={pendingPromise:null,pendingSignature:'',acceptedSignature:'',initialRoomRefreshSeen:false,requestId:0};function getRoomSelect(){if(elements.rooms){return elements.rooms}if(elements.form&&elements.form.elements['rooms[]']){return elements.form.elements['rooms[]']}return null}function getSelectedRoomIds(){var rooms=getRoomSelect(),ids=[],i;if(!rooms||!rooms.options){return ids}for(i=0;i<rooms.options.length;i++){if(rooms.options[i].selected&&rooms.options[i].value!==''){ids.push(parseInt(rooms.options[i].value,10))}}return ids.filter(function(roomid){return!isNaN(roomid)&&roomid>0}).sort(function(a,b){return a-b})}function getSignature(){var courseid=elements.course&&elements.course.value?String(elements.course.value):'0',groupid=elements.group&&elements.group.value?String(elements.group.value):'0',roomids=getSelectedRoomIds();return[courseid,groupid].concat(roomids).join(':')}function hasValidSelection(){return!!(elements.course&&elements.course.value&&getSelectedRoomIds().length)}function requestCapacity(){var url=new URL(config.endpoint,window.location.origin),rooms=getSelectedRoomIds(),i;url.searchParams.set('action','capacity');url.searchParams.set('courseid',elements.course&&elements.course.value?elements.course.value:0);url.searchParams.set('groupid',elements.group&&elements.group.value?elements.group.value:0);for(i=0;i<rooms.length;i++){url.searchParams.append('rooms[]',rooms[i])}return fetch(url.toString(),{credentials:'same-origin'}).then(function(response){if(!response.ok){throw new Error('Request failed')}return response.json()}).then(function(data){if(data.error){throw new Error(data.error)}return data.results||{}})}function showConfirmation(signature){return new Promise(function(resolve){Notification.confirm(config.title,config.message,config.yesLabel,config.noLabel,function(){state.acceptedSignature=signature;resolve(true)},function(){if(config.redirectUrl){window.location.assign(config.redirectUrl)}resolve(false)})})}function check(){var signature=getSignature();if(signature===state.acceptedSignature){return Promise.resolve(true)}if(!hasValidSelection()){state.acceptedSignature=signature;return Promise.resolve(true)}if(state.pendingPromise&&state.pendingSignature===signature){return state.pendingPromise}var requestId=++state.requestId;state.pendingSignature=signature;state.pendingPromise=requestCapacity().then(function(result){if(requestId!==state.requestId){state.pendingPromise=null;return check()}if(signature!==getSignature()){state.pendingPromise=null;return check()}if(!result||!result.blocked){state.acceptedSignature=signature;return true}return showConfirmation(signature)}).catch(function(error){state.pendingPromise=null;if(window.console){window.console.error(error)}return true}).then(function(allow){state.pendingPromise=null;return allow});return state.pendingPromise}function bindEvents(){if(elements.group){elements.group.addEventListener('change',function(){check()})}var roomselect=getRoomSelect();if(roomselect){roomselect.addEventListener('change',function(){check()})}document.addEventListener('block-mrbs:roomsupdated',function(){if(!state.initialRoomRefreshSeen){state.initialRoomRefreshSeen=true;return}check()})}function init(initConfig){config=initConfig||{};elements.form=document.forms[config.formName||'main'];if(!elements.form){return}elements.course=elements.form.elements.courseid;elements.group=elements.form.elements.groupid;elements.rooms=elements.form.elements['rooms[]'];bindEvents();window.MRBSCapacityWarning={check:check}}return{init:init,check:check}});
